import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D0.3 · 协议、状态机与 UI 数据契约","description":"Hearth D0.3 开发增量：核心实体、状态迁移、UI 投影、事件接口和契约测试共同组成一份可实施的协议。","frontmatter":{"title":"D0.3 · 协议、状态机与 UI 数据契约","description":"Hearth D0.3 开发增量：核心实体、状态迁移、UI 投影、事件接口和契约测试共同组成一份可实施的协议。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-0/d0-3.md","filePath":"delivery/stage-0/d0-3.md","lastUpdated":null}'),s={name:"delivery/stage-0/d0-3.md"};function r(h,a,d,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 0 · D0.3 · 3 / 4</p><h1 id="d0-3-·-协议、状态机与-ui-数据契约" tabindex="-1">D0.3 · 协议、状态机与 UI 数据契约 <a class="header-anchor" href="#d0-3-·-协议、状态机与-ui-数据契约" aria-label="Permalink to &quot;D0.3 · 协议、状态机与 UI 数据契约&quot;">​</a></h1><p class="lead">把原型中的状态、主动作、证据和产物变成稳定契约，让真实后端可以逐步替换 mock，而不重写用户路径。</p><p class="page-meta">STAGE 0 · D0.3 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>核心实体、状态迁移、UI 投影、事件接口和契约测试共同组成一份可实施的协议。</div><div><strong>完成门槛</strong>前端不依赖内部数据库字段；核心状态迁移有唯一解释；schema 可版本化；事件流能重建投影；未知状态安全显示为“需要处理”。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>核心实体、状态迁移、UI 投影、事件接口和契约测试共同组成一份可实施的协议。</p><p>Stage 0 的产出是产品真相与实现契约。没有真实任务、可点击原型和可重复评测，后续开发会把假设当成事实。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>一个空仓库、可记录的真实工作样本，以及一位愿意持续反馈的首位用户。</li><li>允许观察全人工流程与直接使用 Codex 的基线，不要求系统已经存在。</li><li>本阶段不接入真实发送、支付、删除或系统设置修改。</li><li>D0.2 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-领域实体与不变量" tabindex="-1">01 · 领域实体与不变量 <a class="header-anchor" href="#_01-·-领域实体与不变量" aria-label="Permalink to &quot;01 · 领域实体与不变量&quot;">​</a></h3><p>定义 Source、Event、Thread、Intent、Task、Ticket、Mandate、Policy、Assignment、Run、Executor、Approval、Artifact、Receipt、Budget 的字段、关系和不可破坏条件。例如同一 Ticket 最多一个有效 Assignment，Artifact 内容寻址，Receipt 必须绑定幂等键。</p><h3 id="_02-·-事件、状态机与投影" tabindex="-1">02 · 事件、状态机与投影 <a class="header-anchor" href="#_02-·-事件、状态机与投影" aria-label="Permalink to &quot;02 · 事件、状态机与投影&quot;">​</a></h3><p>把创建、排队、执行、审批、失败、恢复和完成写成显式事件；任务卡、收件箱、产物和成本都由投影生成。未知事件或未知状态只能进入“需要处理”，不能推断为成功。</p><h3 id="_03-·-持久执行接口" tabindex="-1">03 · 持久执行接口 <a class="header-anchor" href="#_03-·-持久执行接口" aria-label="Permalink to &quot;03 · 持久执行接口&quot;">​</a></h3><p>固定 Event Log、outbox、lease、fencing token、schema migration 和 SSE 的边界。规定先落盘再执行、外部副作用先写 intent、重试复用幂等键，以及崩溃后如何安全重投。</p><h3 id="_04-·-mock-server-与契约测试" tabindex="-1">04 · Mock server 与契约测试 <a class="header-anchor" href="#_04-·-mock-server-与契约测试" aria-label="Permalink to &quot;04 · Mock server 与契约测试&quot;">​</a></h3><p>mock server 只消费同一事件流来驱动原型；为主路径、审批拒绝、未知状态、重复事件和恢复编写契约测试。schema 使用版本号，旧事件重放不能产生外部副作用。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>packages/core/src/schema</code> — 领域实体、状态机与失败分类</li><li><code>packages/eventlog</code> — Event Log、投影与 migration</li><li><code>packages/evals</code> — 任务集、runner、评分与人工复核</li><li><code>apps/web</code> — 今日、需要你、产物、设置与任务详情原型</li><li><code>fixtures/tasks</code> — 真实任务样本与失败样本</li><li><code>docs/adr</code> — Build vs Integrate、事件模型与前端投影决策</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>Event</code></td><td>id、type、schemaVersion、occurredAt、actor、subject、causationId、correlationId、payload；只追加，不能覆盖历史。</td></tr><tr><td><code>TaskCardProjection</code></td><td>taskId、title、state、primaryAction、reason、lastEventAt、artifacts、budget；页面不读取数据库字段。</td></tr><tr><td><code>ExecutorEvent</code></td><td>标准化事件、产物引用、structResult、validation、failureClass、recoverable；执行器不直接写主库。</td></tr><tr><td><code>Approval</code></td><td>effectPreview、scope、expiresAt、decision、idempotencyKey；审批绑定真实动作和参数。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:contract</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:smoke：12</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 个任务可重复跑分</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev：打开桌面与</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 390px</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 手机宽度原型</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-0/d0-3.html">D0.3 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：领域实体与不变量、事件、状态机与投影、持久执行接口、Mock server 与契约测试。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“原型状态无法映射”。页面必须显示“页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。”，然后按“补齐状态映射、更新契约测试，再重新演示原路径。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：前端不依赖内部数据库字段；核心状态迁移有唯一解释；schema 可版本化；事件流能重建投影；未知状态安全显示为“需要处理”。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>领域实体与状态机图</li><li>TaskCard/Approval/Artifact 契约</li><li>mock server 与契约测试</li><li>schema 版本与迁移说明</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 前端不依赖内部数据库字段；核心状态迁移有唯一解释；schema 可版本化；事件流能重建投影；未知状态安全显示为“需要处理”。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>原型状态无法映射</td><td>页面显示“需要处理”，并记录未识别的 projection 字段和任务 ID。</td><td>补齐状态映射、更新契约测试，再重新演示原路径。</td></tr><tr><td>真实任务无法验收</td><td>任务保留在候选池，标注原因，不进入开发承诺。</td><td>补清输入、产物或验收方式，或换一个真实任务。</td></tr><tr><td>基线不可比较</td><td>该任务不进入评测集，避免用失真的数据证明价值。</td><td>重新记录人工分钟、成功率、Token 与失败类型。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不先做完整内核再补界面。</li><li>不用文档完成度替代可点击原型与可重复评测。</li><li>不接入真实高风险外部副作用。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/design/">项目设计与取舍</a></li><li><a href="/hearth-os/reference/checklists.html">默认清单</a></li><li><a href="/hearth-os/architecture/domain-model.html">领域模型与协议</a></li><li><a href="/hearth-os/architecture/evaluation.html">评估体系</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-0/d0-4.html">D0.4 · 评测、安全与工程基线</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
